"Edition": "Ausgabe",
"The Mass, calendar, and prayers Sanctify follows.": "Die Messe, der Kalender und die Gebete, denen Sanctify folgt.",
"Theme": "Design",
"Choose a theme": "Design wählen",
"A metallic sheen on titles and cards, on themes with gold in them.": "Ein metallischer Glanz auf Titeln und Karten, bei Designs mit Gold.",
"A soft light behind pages and banners.": "Ein sanftes Licht hinter Seiten und Bannern.",
"Reduce motion": "Bewegung reduzieren",
"Pages appear without sliding or fading in.": "Seiten erscheinen ohne Gleiten oder Einblenden.",
"Your data": "Deine Daten",
"Your saved entries, novenas, intentions, prayer record, badges, and settings are kept only in this browser. Save a backup to move them to another device.": "Deine gespeicherten Einträge, Novenen, Anliegen, dein Gebetsprotokoll, deine Abzeichen und Einstellungen werden nur in diesem Browser aufbewahrt. Speichere eine Sicherung, um sie auf ein anderes Gerät zu übertragen.",
