"Read Sanctify in your language. Pages are translated by Google, by machine: prayers and Scripture may not match the approved translations used in your country, and Latin texts stay in Latin.": "Lies Sanctify in deiner Sprache. Die Seiten werden von Google maschinell übersetzt: Gebete und Schrift entsprechen vielleicht nicht den in deinem Land approbierten Übersetzungen, und lateinische Texte bleiben lateinisch.",
"Find a language…": "Sprache suchen…",
"A Catholic Repository": "Eine katholische Sammlung",
"The Mass and calendar of the Roman Rite as celebrated in most parishes today.": "Die Messe und der Kalender des Römischen Ritus, wie sie heute in den meisten Pfarreien gefeiert werden.",
"The Missal and calendar of 1962: the Traditional Latin Mass explained, the old feasts, seasons, and Ember Days, and the fifteen mysteries of the Rosary.": "Das Messbuch und der Kalender von 1962: die überlieferte lateinische Messe erklärt, die alten Feste, Zeiten und Quatember und die fünfzehn Geheimnisse des Rosenkranzes.",
"The Byzantine tradition: the Divine Liturgy, the Jesus Prayer, Byzantine prayers, and the Byzantine calendar.": "Die byzantinische Tradition: die Göttliche Liturgie, das Jesusgebet, byzantinische Gebete und der byzantinische Kalender.",
