"Choose another passage": "Eine andere Stelle wählen",
"Begin Lectio Divina": "Lectio Divina beginnen",
"Before you begin": "Bevor du beginnst",
"Completely private.": "Ganz privat.",
"Clear everything": "Alles löschen",
"How to go to Confession": "Wie man beichtet",
"Pray the Act of Contrition": "Das Reuegebet beten",
"Pray the Prayer of St. Ephrem": "Das Gebet des hl. Ephräm beten",
