"follows the Byzantine tradition, shared by the Ukrainian, Ruthenian, Melkite, Romanian, and other Greek Catholic Churches. The Maronite, Syro-Malabar, Chaldean, Armenian, Coptic, and other Eastern Catholic Churches have their own liturgies.": "folgt der byzantinischen Tradition, die die ukrainische, ruthenische, melkitische, rumänische und weitere griechisch-katholische Kirchen teilen. Die maronitische, syro-malabarische, chaldäische, armenische, koptische und andere katholische Ostkirchen haben eigene Liturgien.",
"Eastern Catholic edition": "Ostkatholische Ausgabe",
"About the Eastern Catholic Churches →": "Über die katholischen Ostkirchen →",
