"Pray today": "Heute beten",
"Pray the Jesus Prayer →": "Das Jesusgebet beten →",
"Pray slowly on the prayer rope: “Lord Jesus Christ, Son of God, have mercy on me, a sinner.”": "Bete langsam an der Gebetsschnur: „Herr Jesus Christus, Sohn Gottes, erbarme dich meiner, des Sünders.“",
"{n} prayers as illustrated cards, the Jesus Prayer on a prayer rope, the Trisagion Prayers, and the Prayer of St. Ephrem.": "{n} Gebete als illustrierte Bildchen, das Jesusgebet an der Gebetsschnur, die Trisagion-Gebete und das Gebet des hl. Ephräm.",
