"A weekday in {*} — open the Calendar tab to see what’s coming up.": "Ein Werktag – {*}. Öffne den Kalender, um zu sehen, was kommt.",
"Observances on this day are hidden by your filters.": "Deine Filter blenden die Feiern dieses Tages aus.",
"A season of hopeful preparation for the coming of Christ, both at Christmas and at the end of time.": "Eine Zeit hoffnungsvoller Vorbereitung auf das Kommen Christi, an Weihnachten und am Ende der Zeit.",
"The Church celebrates the birth of Christ, from Christmas Day through the Baptism of the Lord.": "Die Kirche feiert die Geburt Christi, vom Weihnachtstag bis zur Taufe des Herrn.",
"The “ordinal,” or counted, weeks of the year, when the Church reflects on the public life and teaching of Christ.": "Die gezählten Wochen des Jahres, in denen die Kirche das öffentliche Leben und die Lehre Christi betrachtet.",
"Forty days of prayer, fasting, and almsgiving in preparation for Easter.": "Vierzig Tage des Gebets, Fastens und Almosengebens zur Vorbereitung auf Ostern.",
"The three holiest days of the year: the Lord’s Supper, his Passion and death, and his Resurrection.": "Die drei heiligsten Tage des Jahres: das Abendmahl des Herrn, sein Leiden und Sterben und seine Auferstehung.",
"Fifty days of rejoicing in the Resurrection, from Easter Sunday to Pentecost.": "Fünfzig Tage der Freude über die Auferstehung, vom Ostersonntag bis Pfingsten.",
"Four weeks of preparation for the coming of Christ, at Christmas and at the end of time.": "Vier Wochen der Vorbereitung auf das Kommen Christi, an Weihnachten und am Ende der Zeit.",
"From the Nativity to the Commemoration of the Baptism of Our Lord on January 13.": "Von der Geburt des Herrn bis zum Gedächtnis der Taufe unseres Herrn am 13. Januar.",
"The Sundays after the Epiphany, when Christ is made known to the nations.": "Die Sonntage nach Epiphanie, an denen Christus den Völkern offenbar wird.",
"The three weeks before Lent. The Gloria and the Alleluia fall silent, and violet is worn.": "Die drei Wochen vor der Fastenzeit. Gloria und Halleluja verstummen, und man trägt Violett.",
"Forty days of fasting, prayer, and almsgiving, from Ash Wednesday.": "Vierzig Tage des Fastens, Gebets und Almosengebens, ab Aschermittwoch.",
"The last two weeks of Lent, from Passion Sunday through Holy Week. Crosses and images are veiled.": "Die letzten zwei Wochen der Fastenzeit, vom Passionssonntag durch die Karwoche. Kreuze und Bilder werden verhüllt.",
"From Easter Sunday to the Saturday after Pentecost.": "Vom Ostersonntag bis zum Samstag nach Pfingsten.",
"From Trinity Sunday until Advent: the long season of the Church’s growth.": "Vom Dreifaltigkeitssonntag bis zum Advent: die lange Zeit des Wachstums der Kirche.",
"Forty days of fasting and joyful preparation for the Nativity of Christ, from November 15 to December 24.": "Vierzig Tage des Fastens und freudiger Vorbereitung auf die Geburt Christi, vom 15. November bis 24. Dezember.",
"The feasts of the birth of Christ and of his baptism in the Jordan, from December 25 to the leave-taking of Theophany.": "Die Feste der Geburt Christi und seiner Taufe im Jordan, vom 25. Dezember bis zum Abschluss der Theophanie.",
"The weeks of the Triodion that prepare for Great Lent, from the Sunday of the Publican and the Pharisee to Forgiveness Sunday.": "Die Wochen des Triodions, die auf die Große Fastenzeit vorbereiten, vom Sonntag des Zöllners und Pharisäers bis zum Sonntag der Vergebung.",
"Forty days of fasting, prayer, and almsgiving, beginning on Clean Monday.": "Vierzig Tage des Fastens, Gebets und Almosengebens, ab dem Reinen Montag.",
"From Lazarus Saturday and the Entry into Jerusalem through the Passion of Christ to Great and Holy Saturday.": "Vom Lazarus-Samstag und dem Einzug in Jerusalem durch das Leiden Christi bis zum Großen und Heiligen Samstag.",
"Christ is risen! Forty days of Paschal joy, followed by the Ascension and Pentecost.": "Christus ist auferstanden! Vierzig Tage österlicher Freude, gefolgt von Himmelfahrt und Pfingsten.",
"A fast from the Monday after All Saints Sunday until the feast of Sts. Peter and Paul on June 29.": "Ein Fasten vom Montag nach dem Allerheiligensonntag bis zum Fest der hll. Petrus und Paulus am 29. Juni.",
"Two weeks of fasting in honor of the Theotokos, from August 1 to 14, before her Dormition.": "Zwei Wochen des Fastens zu Ehren der Gottesgebärerin, vom 1. bis 14. August, vor ihrem Entschlafen.",
"The Sundays after Pentecost, when the Church follows the public ministry of Christ.": "Die Sonntage nach Pfingsten, an denen die Kirche dem öffentlichen Wirken Christi folgt.",
