"Credits": "Mitwirkende",
"The Sanctify team": "Das Sanctify-Team",
"Sanctify is made and looked after by a small team, and kept friendly by its moderators.": "Sanctify wird von einem kleinen Team gemacht und gepflegt, und die Moderatoren sorgen für einen freundlichen Ton.",
"Administrator": "Administrator",
"The Community": "Die Community",
"Thank you to everyone who posts, prays for others, and writes in the Community Wiki. Many of the changes in Sanctify 0.9 began as members’ suggestions in the forum.": "Danke an alle, die posten, für andere beten und im Community-Wiki schreiben. Viele Änderungen in Sanctify 0.9 begannen als Vorschläge von Mitgliedern im Forum.",
"Scripture and the Catechism": "Die Heilige Schrift und der Katechismus",
"The Bible on the site is the Douay-Rheims, with Bishop Challoner’s notes, which is in the public domain. The Catechism of the Catholic Church is © Libreria Editrice Vaticana.": "Die Bibel auf der Seite ist die Douay-Rheims mit den Anmerkungen von Bischof Challoner; sie ist gemeinfrei. Der Katechismus der Katholischen Kirche ist © Libreria Editrice Vaticana.",
"Images and recordings": "Bilder und Aufnahmen",
"Pictures of the saints, icons, and books, and the hymn recordings, come from Wikipedia and Wikimedia Commons. Each one is credited on the site with its author and license.": "Bilder von Heiligen, Ikonen und Büchern sowie die Hymnenaufnahmen stammen aus Wikipedia und Wikimedia Commons. Jedes ist auf der Seite mit Urheber und Lizenz angegeben.",
"Languages": "Sprachen",
"Sanctify is translated by hand into Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian, with the common prayers in the words Catholics pray in each language.": "Sanctify ist von Hand ins Spanische, Polnische, Französische, Portugiesische, Italienische, Deutsche, Russische und Ukrainische übersetzt, mit den gängigen Gebeten im Wortlaut, wie Katholiken sie in jeder Sprache beten.",
"Type": "Schrift",
"The headings are set in Cormorant Garamond and the text in Source Serif 4, both from Google Fonts under the SIL Open Font License.": "Die Überschriften sind in Cormorant Garamond gesetzt, der Text in Source Serif 4, beide von Google Fonts unter der SIL Open Font License.",
