"Moderators can remove posts and replies, review reports, and mute, warn, or ban members. They get the Moderator badge.": "Moderatoren können Beiträge und Antworten entfernen, Meldungen prüfen und Mitglieder stummschalten, verwarnen oder sperren. Sie bekommen das Moderator-Abzeichen.",
