"Earlier catechisms, now in the public domain, to read right here on Sanctify, a lesson at a time.": "Ältere Katechismen, heute gemeinfrei, hier auf Sanctify Lektion für Lektion zu lesen (auf Englisch).",
"Catechisms of the Christian East": "Katechismen des christlichen Ostens",
"How the Fathers of the East taught the faith to new Christians and to the Church, treasured by Eastern and Latin Catholics alike.": "Wie die Väter des Ostens Neugetaufte und die Kirche im Glauben unterwiesen, von östlichen und lateinischen Katholiken gleichermaßen geschätzt.",
"Shorter companions": "Kürzere Begleiter",
"Official summaries of the Catechism of the Catholic Church, in questions and answers.": "Offizielle Zusammenfassungen des Katechismus der Katholischen Kirche in Frage und Antwort.",
"Our Father, who art in heaven, hallowed be thy name; thy kingdom come; thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. For yours is the kingdom, and the power, and the glory, of the Father, and of the Son, and of the Holy Spirit, now and ever and unto ages of ages. Amen.": "Vater unser im Himmel, geheiligt werde dein Name. Dein Reich komme. Dein Wille geschehe, wie im Himmel, so auf Erden. Unser tägliches Brot gib uns heute. Und vergib uns unsere Schuld, wie auch wir vergeben unsern Schuldigern. Und führe uns nicht in Versuchung, sondern erlöse uns von dem Bösen. Denn dein ist das Reich und die Kraft und die Herrlichkeit, des Vaters und des Sohnes und des Heiligen Geistes, jetzt und immerdar und in alle Ewigkeit. Amen.",
"Glory to the Father, and to the Son, and to the Holy Spirit, now and ever and unto ages of ages. Amen.": "Ehre sei dem Vater und dem Sohn und dem Heiligen Geist, jetzt und immerdar und in alle Ewigkeit. Amen.",
"O Lord and Master of my life, take from me the spirit of sloth, despair, lust of power, and idle talk.": "Herr und Gebieter meines Lebens, den Geist der Trägheit, der Verzagtheit, der Herrschsucht und der Geschwätzigkeit gib mir nicht.",
"But give rather the spirit of chastity, humility, patience, and love to your servant.": "Den Geist der Keuschheit, der Demut, der Geduld und der Liebe aber schenke mir, deinem Diener.",
"Yes, O Lord and King, grant me to see my own transgressions and not to judge my brother, for you are blessed unto ages of ages. Amen.": "Ja, Herr und König, lass mich meine eigenen Verfehlungen sehen und meinen Bruder nicht verurteilen, denn gepriesen bist du in alle Ewigkeit. Amen.",
"About 5 minutes": "Etwa 5 Minuten",
"Beginning": "Beginn",
"In the name of the Father": "Im Namen des Vaters",
"In the Byzantine tradition the Sign of the Cross is made from right to left, with the thumb and first two fingers joined in honor of the Trinity.": "In der byzantinischen Tradition wird das Kreuzzeichen von rechts nach links gemacht, Daumen und die ersten beiden Finger zu Ehren der Dreifaltigkeit zusammengelegt.",
"To the Holy Spirit": "An den Heiligen Geist",
"O Heavenly King": "Himmlischer König",
"The Thrice-Holy Hymn": "Der dreimal heilige Gesang",
"Pray it three times, making the Sign of the Cross and bowing each time.": "Bete es dreimal, jedes Mal mit Kreuzzeichen und Verneigung.",
"Three times": "Dreimal",
"To the Holy Trinity": "An die Heilige Dreifaltigkeit",
"Glory… O Most Holy Trinity": "Ehre… Allheilige Dreifaltigkeit",
"Conclusion": "Abschluss",
"Lord, have mercy": "Herr, erbarme dich",
"Pray it twelve times.": "Bete es zwölfmal.",
"Through the prayers of our holy fathers, Lord Jesus Christ our God, have mercy on us and save us. Amen.": "Auf die Gebete unserer heiligen Väter, Herr Jesus Christus, unser Gott, erbarme dich unser und rette uns. Amen.",
"I believe, O Lord": "Ich glaube, Herr",
"The Mystical Supper": "Das Mystische Abendmahl",
"Of your mystical supper": "An deinem mystischen Mahl",
"For healing": "Zur Heilung",
"Not unto judgment": "Nicht zum Gericht",
"The prayer of the publican": "Das Gebet des Zöllners",
"O God, be merciful to me": "Gott, sei mir gnädig",
"Pray it three times, bowing each time.": "Bete es dreimal, jedes Mal mit einer Verneigung.",
"Remember me, O Lord, in your kingdom.": "Gedenke meiner, o Herr, in deinem Reich.",
"The Angelic Salutation": "Der Englische Gruß",
"Rejoice, O Virgin Theotokos": "Freue dich, jungfräuliche Gottesgebärerin",
"Axion Estin": "Axion estin",
"The oldest Marian prayer": "Das älteste Mariengebet",
"Beneath Your Compassion": "Unter deinen Schutz und Schirm",
"Most Holy Theotokos, save us": "Allheilige Gottesgebärerin, rette uns",
"More honorable than the Cherubim, and beyond compare more glorious than the Seraphim.": "Ehrwürdiger als die Cherubim und unvergleichlich herrlicher als die Serafim.",
"First part": "Erster Teil",
"O Lord and Master of my life": "Herr und Gebieter meines Lebens",
"Make a prostration.": "Mach eine Prostration.",
"Second part": "Zweiter Teil",
"But give rather": "Schenke mir vielmehr",
"Third part": "Dritter Teil",
"Yes, O Lord and King": "Ja, Herr und König",
"Twelve bows": "Zwölf Verneigungen",
"O God, cleanse me, a sinner": "Gott, reinige mich Sünder",
"Bow from the waist twelve times, praying these words each time.": "Verneige dich zwölfmal tief und bete jedes Mal diese Worte.",
"Once more": "Noch einmal",
"The whole prayer": "Das ganze Gebet",
"Pray the whole prayer again, and make one final prostration.": "Bete das ganze Gebet noch einmal und mach eine letzte Prostration.",
"Grant me to see my own transgressions, and not to judge my brother.": "Lass mich meine eigenen Verfehlungen sehen und meinen Bruder nicht verurteilen.",
"Stillness": "Stille",
"Come before God": "Tritt vor Gott",
"For whom am I grateful today?": "Für wen bin ich heute dankbar?",
"Where did I see God’s goodness?": "Wo habe ich Gottes Güte gesehen?",
"What grace carried me through a hard moment?": "Welche Gnade hat mich durch einen schweren Moment getragen?",
"Watchfulness": "Wachsamkeit",
"Look into your heart": "Schau in dein Herz",
"Which thoughts did I welcome that led me away from God?": "Welche Gedanken habe ich zugelassen, die mich von Gott wegführten?",
"Where did I judge my brother or sister?": "Wo habe ich meinen Bruder oder meine Schwester verurteilt?",
"Where did I love, forgive, or serve?": "Wo habe ich geliebt, vergeben oder gedient?",
